#!/bin/bash
set -e
# Setup for Question 1: kubeconfig with multiple contexts and client certificates.
mkdir -p /tmp/exam/1

cat > /tmp/exam/1/kubeconfig <<'EOF'
apiVersion: v1
kind: Config
clusters:
- name: cluster-admin
  cluster:
    server: https://cluster-admin.example:6443
    insecure-skip-tls-verify: true
- name: cluster-w100
  cluster:
    server: https://cluster-w100.example:6443
    insecure-skip-tls-verify: true
- name: cluster-w200
  cluster:
    server: https://cluster-w200.example:6443
    insecure-skip-tls-verify: true
users:
- name: admin@internal
  user:
    token: admin-token
- name: account-0027@internal
  user:
    client-certificate-data: 
- name: account-0028@internal
  user:
    client-certificate-data: 
contexts:
- name: cluster-admin
  context:
    cluster: cluster-admin
    user: admin@internal
- name: cluster-w100
  context:
    cluster: cluster-w100
    user: account-0027@internal
- name: cluster-w200
  context:
    cluster: cluster-w200
    user: account-0028@internal
current-context: cluster-w200
EOF

chmod 600 /tmp/exam/1/kubeconfig
echo "Setup completed for Question 1"
